ref("31595543","Huegel","Huegel J, et al.",2019,"Effects of Pulsed Electromagnetic Field Therapy on Rat Achilles Tendon Healing.","J Orthop Res","38(1):70-81","10.1002/jor.24487","PMC6917903","animal",["muscular"],["induction"],"0","Rat Achilles injury models given Physio-Stim-type PEMF 1 or 3 h/day: no clear healing benefit, and some decreases in tendon mechanics/ankle function after complete tear, i.e. null/possibly negative in contrast to rotator cuff.")
